static const z_t5517_t _zag1532 = { { .data = "win_utf8", .size = 8 }, { .length = 1, .data = _zag1531 }, { .length = 1, .data = _zag1529 }, { .data = "static char* z_win_utf8(const wchar_t* w, int wn, size_t* len) {\n    int n = WideCharToMultiByte(CP_UTF8, 0, w, wn, NULL, 0, NULL, NULL);\n    if (n == 0 && wn != 0) return NULL;\n    char* s = (char*)z_xmalloc((size_t)n + 1);\n    if (n > 0) WideCharToMultiByte(CP_UTF8, 0, w, wn, s, n, NULL, NULL);\n    /* a NUL-terminated source counts its terminator */\n    if (wn < 0 && n > 0) n--;\n    s[n] = '\\0';\n    if (len) *len = (size_t)n;\n    return s;\n}", .size = 447 } };
