static const z_t59_t _zag3174[] = {{ .data = "prelude.@acqrel", .size = 15 }, { .data = "prelude.@atomic_sub", .size = 19 }, { .data = "prelude.@cond_destroy", .size = 21 }, { .data = "prelude.@mutex_destroy", .size = 22 }};

